code='''from collections import Counter, deque
from itertools import permutations

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if cells == border:
                frames.append((color, r0, r1, c0, c1, cells))
    if not frames:
        return [row[:] for row in grid]
    border_cells = set().union(*(f[5] for f in frames))
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r,c) not in border_cells)
    marker_colors = sorted(counts)
    targets = []
    for _, r0, r1, c0, c1, _ in frames:
        targets.append(sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1)
                           if (r-r0-1 + c-c0-1) % 2 == 0))
    if len(marker_colors) >= len(frames):
        assignment = min(permutations(marker_colors, len(frames)),
                         key=lambda p: sum(abs(counts[col]-target) for col,target in zip(p,targets)))
    else:
        assignment = tuple(min(marker_colors, key=lambda col: abs(counts[col]-target)) for target in targets)
    out = [[0]*w for _ in range(h)]
    for i, (border_color, r0, r1, c0, c1, cells) in enumerate(frames):
        fill = assignment[i]
        for r,c in cells:
            out[r][c] = border_color
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r-r0-1 + c-c0-1) % 2 == 0:
                    out[r][c] = fill
    return out
'''
